import{_ as e,a as r,o as a,a6 as d}from"./chunks/framework.CJDy2q7X.js";const p=JSON.parse('{"title":"Create-Order Helpers","description":"","frontmatter":{"outline":false,"apiType":"rest"},"headers":[],"relativePath":"api/rest-api/admin/customers/create-order-helpers/index.md","filePath":"api/rest-api/admin/customers/create-order-helpers/index.md","lastUpdated":1786429091000}'),s={name:"api/rest-api/admin/customers/create-order-helpers/index.md"};function o(i,t,n,h,c,l){return a(),r("div",null,t[0]||(t[0]=[d('<h1 id="create-order-helpers" tabindex="-1">Create-Order Helpers <a class="header-anchor" href="#create-order-helpers" aria-label="Permalink to &quot;Create-Order Helpers&quot;">​</a></h1><p>The Create-Order Helpers are read-only panels that support an admin <strong>placing an order on a customer&#39;s behalf</strong>. When building an order from the admin side, you often want to seed it from what the customer already has — their live cart, their wishlist, or things they bought before. These endpoints surface exactly that, so the admin can pick products into a draft cart without hunting through the catalog. They back the sidebar panels of the admin Create-Order screen.</p><h2 id="how-they-fit-the-create-order-flow" tabindex="-1">How they fit the Create-Order flow <a class="header-anchor" href="#how-they-fit-the-create-order-flow" aria-label="Permalink to &quot;How they fit the Create-Order flow&quot;">​</a></h2><p>The full order-building flow lives under <a href="/api/rest-api/admin/sales/orders/">Sales → Orders</a> (create a draft cart, add items, save addresses, choose shipping/payment, place the order). These helpers are the supporting reads for that flow — they tell you what to add. The one write here, <strong>Create Draft Cart</strong>, is the entry point that starts a fresh draft cart for the customer.</p><table tabindex="0"><thead><tr><th>Helper</th><th>What it shows</th></tr></thead><tbody><tr><td>Active Cart Items</td><td>The items currently in the customer&#39;s own active storefront cart.</td></tr><tr><td>Wishlist Items</td><td>The products on the customer&#39;s wishlist.</td></tr><tr><td>Recent Order Items</td><td>The most recently ordered products (up to the last five distinct products).</td></tr><tr><td>Create Draft Cart</td><td>Starts a new empty draft cart for the customer to build the order in.</td></tr></tbody></table><h2 id="endpoints-in-this-menu" tabindex="-1">Endpoints in this menu <a class="header-anchor" href="#endpoints-in-this-menu" aria-label="Permalink to &quot;Endpoints in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Endpoint</th></tr></thead><tbody><tr><td><a href="./../active-cart-items.html">Active Cart Items</a></td><td><code>GET /api/admin/customers/{customerId}/cart-items</code></td></tr><tr><td><a href="./../wishlist-items.html">Wishlist Items</a></td><td><code>GET /api/admin/customers/{customerId}/wishlist-items</code></td></tr><tr><td><a href="./../recent-order-items.html">Recent Order Items</a></td><td><code>GET /api/admin/customers/{customerId}/recent-order-items</code></td></tr><tr><td><a href="./../create-draft-cart.html">Create Draft Cart</a></td><td><code>POST /api/admin/customers/{customerId}/draft-carts</code></td></tr></tbody></table><p>All endpoints require an admin Bearer token — see <a href="/api/rest-api/admin/authentication.html">Authentication</a>.</p>',8)]))}const u=e(s,[["render",o]]);export{p as __pageData,u as default};
